<script setup lang="ts">import type {ContainerInfo} from '~/types';const open=defineModel<boolean>('open',{default:false});defineProps<{containers:ContainerInfo[]}>();const {networks,create,update,remove}=useManagedNetworks();const name=ref('');async function add(){if(name.value.trim()){await create({name:name.value,scope:'selected'});name.value=''}}async function toggle(n:any,id:string){await update(n.id,{workerIds:n.workerIds.includes(id)?n.workerIds.filter((x:string)=>x!==id):[...n.workerIds,id]})}</script><template><UModal v-model:open="open" title="Managed networks" data-testid="managed-networks"><template #body><form class="flex gap-2" @submit.prevent="add"><UInput v-model="name" aria-label="Network name" placeholder="Network name"/><UButton type="submit">Create network</UButton></form><p class="mt-2 text-xs text-gray-500">Management networks are never attachable here.</p><section v-for="network in networks" :key="network.id" class="mt-4 rounded border p-3"><div class="flex justify-between"><strong>{{network.name}}</strong><UButton size="xs" color="error" variant="ghost" @click="remove(network.id)">Delete</UButton></div><label v-for="worker in containers.filter(x=>x.userId===network.userId)" :key="worker.id" class="block mt-2"><input type="checkbox" :checked="network.workerIds.includes(worker.id)" @change="toggle(network,worker.id)"> {{worker.displayName}}</label></section></template></UModal></template>
